FLWStoryState& ALWStoryDirector::State()const{return Player->RPG.Story;}
ALWStoryDirector::ALWStoryDirector(){PrimaryActorTick.bCanEverTick=true;RootComponent=CreateDefaultSubobject<USceneComponent>(TEXT("Root"));Camera=CreateDefaultSubobject<UCameraComponent>(TEXT("StoryCamera"));Camera->SetupAttachment(RootComponent);Camera->FieldOfView=68;SceneLight=CreateDefaultSubobject<UPointLightComponent>(TEXT("CinematicFill"));SceneLight->SetupAttachment(Camera);SceneLight->SetRelativeLocation(FVector(30,0,35));SceneLight->SetIntensity(90000);SceneLight->SetAttenuationRadius(2000);SceneLight->SetCastShadows(false);SceneLight->SetVisibility(false);}
ALWStoryDirector* ALWStoryDirector::Ensure(ALWCharacter* P){if(!P||!P->World)return nullptr;if(!IsValid(P->Story)){auto* D=P->GetWorld()->SpawnActor<ALWStoryDirector>();D->Player=P;D->World=P->World;P->Story=D;}return P->Story;}
FVector ALWStoryDirector::At(int32 I,FVector Local)const{return FVector(LWStory::Site(I),30)+Local;}
FVector ALWStoryDirector::Target()const{const auto& M=LWStory::Missions()[FMath::Clamp(State().Stage,0,29)];for(auto& N:Nodes)if(IsValid(N)&&Available(N->Action))return N->GetActorLocation();if(FCString::Strlen(M.Action))for(auto& N:Nodes)if(IsValid(N)&&N->Action==M.Action)return N->GetActorLocation();for(auto& E:Enemies)if(IsValid(E)&&!E->bDead)return E->GetActorLocation();if(State().Stage==3||State().Stage==7||State().Stage==13||State().Stage==17){const FName Who=State().Stage==7?TEXT("story_jonah"):State().Stage==13?TEXT("story_inez"):TEXT("story_mara");if(auto* N=People.FindRef(Who).Get())return N->GetActorLocation();}return M.Site<0?ALWWorld::BunkerSpawn():At(M.Site,FVector(0,-2300,100));}
// Chapter 1 is retired. Retain the director type only for legacy references.
void ALWStoryDirector::Start(bool Fresh){ClearActors();State().Enabled=false;Player->bStoryLocked=false;InScene=Choosing=Failed=false;SetActorTickEnabled(false);}
void ALWStoryDirector::Route(){Player->SetWaypoint(FVector2D(Target()));}
void ALWStoryDirector::ClearActors(bool All){if(SceneAudio){SceneAudio->Stop();SceneAudio->DestroyComponent();SceneAudio=nullptr;}if(Transport)Transport->DestroyComponent();Transport=nullptr;for(auto& F:Fire)if(F)F->DestroyComponent();Fire.Empty();for(auto& A:Actors)if(IsValid(A))A->Destroy();Actors.Empty();Enemies.Empty();People.Empty();Nodes.Empty();if(All){for(auto& S:Sites)if(IsValid(S.Value))S.Value->Destroy();Sites.Empty();SiteRevisions38.Empty();}}
void ALWStoryDirector::EndPlay(const EEndPlayReason::Type R){ClearActors();if(Player){Player->bStoryLocked=false;if(auto* PC=Cast<APlayerController>(Player->Controller))PC->SetViewTarget(Player);}Super::EndPlay(R);}
void ALWStoryDirector::Advance(){auto& S=State();if(S.Stage>=29)return;if(!S.Paid.Contains(S.Stage)){S.Paid.Add(S.Stage);Player->GainXP(S.Stage<8?60:180);if(S.Stage>=9)Player->Money+=35;}S.Stage++;if(S.Stage>=LWStory::Complete)Player->MissionRecovery37.Remove(TEXT("chapter1"));S.SceneFinished=false;S.BossWave=0;Player->ClosePanels();Choosing=false;Applied=-1;ApplyStage();Player->RequestSave40();}
