 const auto Posts=LWChapter52::Posts(I,S);TArray<FVector> UsedPosts;for(int K=0;K<M.Enemies;K++){FVector Pos=At(I,Posts[K%Posts.Num()]);auto Clear=[&](FVector V){return FVector::Dist2D(V,Player->GetActorLocation())>=900&&!UsedPosts.ContainsByPredicate([&](FVector U){return FVector::Dist2D(U,V)<180;});};if(!Clear(Pos)){for(const FVector& Alternative:Posts)if(Clear(At(I,Alternative))){Pos=At(I,Alternative);break;}}if(!Clear(Pos))Pos=At(I,FVector(-3700+K*240,-3300,110));UsedPosts.Add(Pos);Enemy(K,Pos,S>=21,(S==19&&K==0)?1:(S==26&&K==0)?2:0);}
 if(S==26){Node(TEXT("shield_a"),TEXT("Destroy west command relay"),Objective52(TEXT("shield_a")),TEXT("Generator"));Node(TEXT("shield_b"),TEXT("Destroy east command relay"),Objective52(TEXT("shield_b")),TEXT("Generator"));}
 else if(S==12||S==18){FString Prefix=S==12?TEXT("relay"):TEXT("breach");Node(FName(*(Prefix+TEXT("_a"))),S==12?TEXT("Start the relay generator"):TEXT("Disable west defense relay"),Objective52(FName(*(Prefix+TEXT("_a")))),TEXT("Generator"));Node(FName(*(Prefix+TEXT("_b"))),S==12?TEXT("Align the transmitter"):TEXT("Disable east defense relay"),Objective52(FName(*(Prefix+TEXT("_b")))),S==12?TEXT("RelayConsole52"):TEXT("Generator"));}
 else if(FCString::Strlen(M.Action)&&FString(M.Action)!=TEXT("mara")&&FString(M.Action)!=TEXT("jonah")&&FString(M.Action)!=TEXT("inez")&&FString(M.Action)!=TEXT("mara_plan")){
 Node(M.Action,M.Objective,Objective52(M.Action),LWChapter52::Prop(M.Action));}
 if(S==10){auto* Patient=Person(TEXT("story_tessa"),TEXT("Tessa Ward"),At(2,FVector(-2450,0,110)),2);if(Patient){Patient->Health=State().Flags.Contains(TEXT("triage"))?150:30;Patient->Say(State().Flags.Contains(TEXT("triage"))?TEXT("The pharmacy cabinet. Please take what you need."):TEXT("Over here. I cannot stop the bleeding."));}Node(TEXT("triage"),TEXT("Dress the survivor's wounds"),Objective52(TEXT("triage")),TEXT("MedicalCase52"));Node(TEXT("pharmacy"),TEXT("Release the pharmacy cabinet latch"),Objective52(TEXT("pharmacy")),TEXT("EvidenceCabinetV18"));}
 if(S==26&&State().BossWave>0)for(int K=20;K<24;K++)Enemy(K,At(8,FVector((K%2?1:-1)*2700,2300+(K%2)*500,110)),true);
 if(S==7||S==8||S>=24){Person(TEXT("story_elsie"),TEXT("Elsie Park"),At(I,FVector(-650,-2700,100)),2);Person(TEXT("story_tomas"),TEXT("Tomas Bell"),At(I,FVector(650,-2700,100)),0);if(S>=24)Person(TEXT("story_inez"),TEXT("Inez Soto"),At(I,FVector(900,-2450,100)),2);}
 if(S>=24&&S<=26){int K=0;for(auto& Pair:People){auto* N=Pair.Value.Get();if(N){N->SetActorLocation(At(8,FVector(3350,-2350+K*320,110)));K++;}}}
 if(S==7)if(auto* N=People.FindRef(TEXT("story_jonah")).Get())N->SetActorLocation(At(1,FVector(-2300,200,110)));
